policy.statement:
forbid (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  exists (sameChangeResponses: Long).
    (count for (t: Timepoint).
      where (formerly within 1h (AgentCore::Action::"SyntheticTools___execute_write"::response{
        eventResource: resource,
        input.change.change_id: context.input.change.change_id,
        output.status: "FAILED"
      } && tp(t)))) == sameChangeResponses
    && sameChangeResponses >= 3
};

forbid (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  exists (sameChangeResponses: Long).
    (count for (t: Timepoint).
      where (formerly within 1h (AgentCore::Action::"SyntheticTools___execute_write"::response{
        eventResource: resource,
        input.change.change_id: context.input.change.change_id,
        output.status: "FAILED"
      } && tp(t)))) == sameChangeResponses
    && sameChangeResponses >= 3
};

forbid (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  exists (successfulWrites: Long).
    (count for (t: Timepoint).
      where (formerly within 24h (AgentCore::Action::"SyntheticTools___execute_write"::response{
        eventResource: resource,
        output.status: "SUCCEEDED"
      } && tp(t)))) == successfulWrites
    && successfulWrites >= 3
};

forbid (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  exists (successfulWrites: Long).
    (count for (t: Timepoint).
      where (formerly within 24h (AgentCore::Action::"SyntheticTools___execute_write"::response{
        eventResource: resource,
        output.status: "SUCCEEDED"
      } && tp(t)))) == successfulWrites
    && successfulWrites >= 3
};

permit (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  formerly within 10m AgentCore::Action::"SyntheticTools___lookup_record"::response{
    eventResource: resource,
    output.record_id: context.input.record_id
  }
  && !AgentCore::Action::"SyntheticTools___execute_write"::response{
    eventResource: resource,
    output.approval_id: context.input.change.approval_id,
    output.status: "SUCCEEDED"
  }
  since within 5m AgentCore::Action::"SyntheticTools___record_human_approval"::response{
    eventResource: resource,
    input.record_id: context.input.record_id,
    input.approval_id: context.input.change.approval_id,
    output.valid: true
  }
};

permit (
  principal == AgentCore::IamEntity::"<REDACTED_SESSION>",
  action == AgentCore::Action::"SyntheticTools___execute_write",
  resource == AgentCore::Gateway::"<REDACTED_SESSION>"
)
when temporal {
  formerly within 10m AgentCore::Action::"SyntheticTools___lookup_record"::response{
    eventResource: resource,
    output.record_id: context.input.record_id
  }
  && !AgentCore::Action::"SyntheticTools___execute_write"::response{
    eventResource: resource,
    output.approval_id: context.input.change.approval_id,
    output.status: "SUCCEEDED"
  }
  since within 5m AgentCore::Action::"SyntheticTools___record_human_approval"::response{
    eventResource: resource,
    input.record_id: context.input.record_id,
    input.approval_id: context.input.change.approval_id,
    output.valid: true
  }
};
